"use client";

import {Tooltip, Button} from "@heroui/react";

export default function App() {
  return (
    <div className="flex gap-2">
      <Tooltip color="success" content="Tooltip 1">
        <Button color="success" variant="faded">
          Default offset (7)
        </Button>
      </Tooltip>
      <Tooltip color="success" content="Tooltip 2" offset={15}>
        <Button color="success" variant="faded">
          15 offset
        </Button>
      </Tooltip>
      <Tooltip color="success" content="Tooltip 3" offset={-7}>
        <Button color="success" variant="faded">
          -7 offset
        </Button>
      </Tooltip>
    </div>
  );
}

"use client";

import {Tooltip, Button} from "@heroui/react";

export default function App() {
  const placements = [
    "top-start",
    "top",
    "top-end",
    "bottom-start",
    "bottom",
    "bottom-end",
    "left-start",
    "left",
    "left-end",
    "right-start",
    "right",
    "right-end",
  ];

  return (
    <div className="flex flex-wrap md:inline-grid md:grid-cols-3 gap-4">
      {placements.map((placement) => (
        <Tooltip key={placement} color="secondary" content={placement} placement={placement}>
          <Button className="capitalize" color="secondary" variant="flat">
            {placement}
          </Button>
        </Tooltip>
      ))}
    </div>
  );
}

